## Flag Resolution Analysis of `app.jar`

### Reconstructed Source (verified by behavioral testing)

```java
package demo;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class Flags {
    // --- built-in: empty LinkedHashMap (Java 9+ List.of / of() vararg) ---
    private static Map<String, Boolean> layer(String... entries) {
        Map<String, Boolean> map = new LinkedHashMap<>();
        for (int i = 0; i < entries.length; i += 2) {
            map.put(entries[i], Boolean.parseBoolean(entries[i + 1]));
        }
        return map;
    }

    static boolean resolve(String key,
            Map<String, Boolean> overridden,
            Map<String, Boolean> environmental) {
        // ① built-in defaults (hard-coded)
        Map<String, Boolean> defaults = layer(
            "beta",  "false",
            "compact", "true"
        );
        // ② layered lookup — first-wins
        for (Map<String, Boolean> layer : List.of(overridden,
                                                 environmental,
                                                 defaults)) {
            Boolean value = layer.get(key);
            if (value != null) return value.booleanValue();
        }
        return false;  // unreachable for known keys (defaults cover them)
    }

    public static void main(String[] args) {
        // ③ two empty maps, then CLI parsing
        Map<String, Boolean> overridden   = layer();   // empty
        Map<String, Boolean> environmental = layer();  // empty

        for (String arg : args) {
            String[] parts = arg.split("=", 2);
            if (parts.length != 2) continue;   // skip malformed

            if (parts[0].startsWith("o:")) {  // "overridden"
                overridden.put(parts[0].substring(2),
                    Boolean.parseBoolean(parts[1]));
            } else if (parts[0].startsWith("e:")) {  // "environmental"
                environmental.put(parts[0].substring(2),
                    Boolean.parseBoolean(parts[1]));
            }
            // anything without o: or e: prefix is silently discarded
        }

        System.out.println("beta=" + resolve("beta", overridden, environmental));
        System.out.println("compact=" + resolve("compact", overridden, environmental));
    }
}
